-- Server-side reminders + watchdog (Joe 2026-10-15, weakness #6). Run this once in the Supabase SQL editor (project idzkigmvovehjpapatxv).
-- It (1) queues tomorrow morning's texts so they no longer depend on the Claude app being open, and (2) starts the every-minute timer that sends
-- due messages and runs the watchdog. The sender function `scheduled-messages` and the table `scheduled_messages` already exist.


select cron.unschedule('scheduled-messages') where exists (select 1 from cron.job where jobname = 'scheduled-messages');
select cron.schedule('scheduled-messages', '* * * * *', $c$ select net.http_post(url := 'https://idzkigmvovehjpapatxv.supabase.co/functions/v1/scheduled-messages', headers := jsonb_build_object('Content-Type','application/json'), body := jsonb_build_object('secret', (select secret from ad_followup_auth where id = 1)), timeout_milliseconds := 55000); $c$);

-- Check: 8 pending messages and the timer is on.
select (select count(*) from public.scheduled_messages where status = 'pending') as pending, (select schedule from cron.job where jobname = 'scheduled-messages') as timer;
